"""This file contains the 3D Dicom Import Validation Tool Page Object class in XVI"""

import logging
from .. interactions import Dicom3DImportFuncs
import time
from interops.libraries.desktop import AutManager
from interops.libraries.xvi import XviAutController
from interops.libraries.squish_actions.constants import XVI_APP_NAME

logger = logging.getLogger(__name__)

class Dicom3DImportTool():

    def __init__(self, host_address="192.168.30.4") -> None:
        # Check if squish has already attached to XVI SRI app, if not attach to it
        if not AutManager.is_aut_running(XVI_APP_NAME):
            xvi_sri_driver = XviAutController.xvi_aut(serverAddress=host_address, serverPort=4322)
            xvi_sri_driver.attach_to_aut()

    def ready(self, ready_timeout: int = 3000) -> bool:
        '''
        Waits for the 3D Dicom Import Validation Tool window to be ready.

        Args:
            ready_timeout (int): Time in milliseconds to wait for the Dicom Import Validation Tool window to be ready

        Returns:
            bool - True if 3D Dicom Import Validation Tool window is ready, False otherwise
        '''
        try:
            return Dicom3DImportFuncs.wait_for_main_dicom_3d_import_validation_tool_window(wait_timeout=ready_timeout)

        except Exception:
            logger.info("3D Dicom Import Validation Tool window failed to open")
            return False

    def select_dicom_data_from_set_list(self, set_count_number:int=1):
        '''
        Selects the specified Dicom data set item based on the Set Count number from the Dicom Set List pane

        Args:
            set_count_number (int): Number of the Dicom data set to import, starting at 1
        '''
        Dicom3DImportFuncs.select_dicom_data_set_item(dicom_data_set_count_number=set_count_number)

    def select_dicom_import_button(self) -> None:
        '''
        Clicks the Import button on the Dicom Import Validation Tool window
        '''
        Dicom3DImportFuncs.click_main_import_button()

    def select_dicom_delete_button(self) -> None:
        '''
        Clicks the Delete button on the Dicom Import Validation Tool window
        '''
        Dicom3DImportFuncs.click_import_delete_button()

    def select_dicom_close_button(self) -> None:
        '''
        Clicks the Close button on the Dicom Import Validation Tool window
        '''
        Dicom3DImportFuncs.click_import_close_button()

    def select_dicom_refresh_button(self) -> None:
        '''
        Clicks the Refresh button on the Dicom Import Validation Tool window
        '''
        Dicom3DImportFuncs.click_import_refresh_button()

    def check_dicom_interpolate_contours_checkbox(self) -> None:
        '''
        Selects the Interpolate Contours checkbox on the Dicom Import Validation Tool window
        '''
        Dicom3DImportFuncs.check_import_interpolate_contours_checkbox()

    def acknowledge_selected_dicom_set_check_dialog_with_yes_button(self, set_check_dialog_timeout: int=8000) -> None:
        '''
        Selects the Yes button on the Selected DICOM set check warning dialog
        (displayed after the import button is pressed)

        Args:
            set_check_dialog_timeout (int): Time in milliseconds to wait for the Selected DICOM set check dialog
        '''
        Dicom3DImportFuncs.click_yes_button_in_selected_dicom_set_check_dialog(set_check_dialog_timeout)

    def acknowledge_selected_dicom_set_check_dialog_with_no_button(self, set_check_dialog_timeout: int=8000) -> None:
        '''
        Selects the No button on the Selected DICOM set check warning dialog
        (displayed after the import button is pressed)

        Args:
            set_check_dialog_timeout (int): Time in milliseconds to wait for the Selected DICOM set check dialog
        '''
        Dicom3DImportFuncs.click_no_button_in_selected_dicom_set_check_dialog(set_check_dialog_timeout)
